CREATE ROLE ReportReaders;
GRANT SELECT ON SCHEMA::Reporting TO ReportReaders;
DENY  SELECT ON Reporting.PayrollSummary TO ReportReaders;   -- deny beats the schema grant
ALTER ROLE ReportReaders ADD MEMBER [analyst@contoso.com];

GRANT EXECUTE ON SCHEMA::Api TO AppRole;   -- procedures as the access surface

-- In the user database (Azure SQL)
CREATE USER [orders-api] FROM EXTERNAL PROVIDER;   -- managed identity of the app
ALTER ROLE db_datareader ADD MEMBER [orders-api];
GRANT EXECUTE ON SCHEMA::Api TO [orders-api];

-- .NET connection string (no password):
-- Server=tcp:myserver.database.windows.net;Database=Orders;
-- Authentication=Active Directory Managed Identity;

-- SQL Server / Managed Instance
CREATE SERVER AUDIT PayrollAudit TO FILE (FILEPATH = 'D:\Audit\');
ALTER SERVER AUDIT PayrollAudit WITH (STATE = ON);

CREATE DATABASE AUDIT SPECIFICATION PayrollAccess
FOR SERVER AUDIT PayrollAudit
    ADD (SELECT, UPDATE ON dbo.Payroll BY public),
    ADD (SCHEMA_OBJECT_CHANGE_GROUP)
WITH (STATE = ON);

SELECT event_time, server_principal_name, statement
FROM sys.fn_get_audit_file('D:\Audit\*.sqlaudit', DEFAULT, DEFAULT);
